UPDATE reservation
SET reservation_status = 'CHECKED_IN'
WHERE reservation_id = #{reservationId}

UPDATE reservation
SET reservation_status = 'CHECKED_OUT'
WHERE reservation_id = #{reservationId}

UPDATE reservation
SET reservation_status = 'NO_SHOW'
WHERE reservation_id = #{reservationId}

mapper.select:
SELECT reservation_status, checkin_date
FROM reservation
WHERE reservation_id = #{reservationId}

SELECT * FROM ( SELECT inner_query.*, ROWNUM AS rnum FROM ( SELECT r.reservation_id, m.name, h.hotel_name, rt.room_type_id, r.checkin_date, r.checkout_date, r.total_price, p.payment_status, r.reservation_status, r.created_at FROM reservation r
JOIN tbl_member_security m ON r.member_no = m.member_no
JOIN room_type rt ON r.room_type_id = rt.room_type_id
JOIN tbl_hotel h ON rt.fk_hotel_id = h.hotel_id
LEFT JOIN payment p ON r.payment_id = p.payment_id
AND m.name LIKE '%' || #{name} || '%'
AND r.reservation_status = #{status}
AND h.hotel_id = #{hotelId}
ORDER BY r.created_at DESC ) inner_query WHERE ROWNUM <= #{offset} + #{limit} ) WHERE rnum > #{offset}
